values
  ('00000000-0000-0000-0000-000000000001', 'MacBook Neo 13', 'Apple', 899, 'Apple M4 (8-core)', 'Integrated M4 8-core', 8, 256, 13.4, 'IPS Retina 60Hz', 1.24, 17, 'macOS', ARRAY['student', 'office', 'web', 'content']::text[], 58, 92, 82, 68, 1, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=silver%20macbook%20neo%2013%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://apple.com/macbook-neo', 'Entry-level Apple laptop. Great battery, quiet fanless design. Limited RAM (8GB) not ideal for heavy multitasking or large codebases.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
  ('00000000-0000-0000-0000-000000000002', 'Dell XPS 13 2026', 'Dell', 1099, 'Intel Core Ultra 5 246V', 'Intel Arc 140V integrated', 16, 512, 13.4, 'OLED InfinityEdge 120Hz', 1.19, 15, 'Windows 11', ARRAY['business', 'office', 'web', 'student', 'content']::text[], 65, 94, 74, 74, 1, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=dell%20xps%2013%202026%20silver%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://dell.com/xps-13', 'Iconic ultrabook. Beautiful OLED, 16GB RAM, 512GB SSD. Solid all-rounder for business and content creation on the go.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
