  ('00000000-0000-0000-0000-000000000004', 'Lenovo IdeaPad Slim 5', 'Lenovo', 699, 'AMD Ryzen 7 8845HS', 'AMD Radeon 780M integrated', 16, 512, 14, 'IPS WUXGA 90Hz', 1.39, 14, 'Windows 11', ARRAY['student', 'office', 'content', 'gaming_light']::text[], 68, 82, 90, 70, 1, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=lenovo%20ideapad%20slim%205%20blue%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://lenovo.com/ideapad-slim-5', 'Best-in-class value. 16GB RAM, strong Ryzen 7, excellent iGPU for light gaming and media editing.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
  ('00000000-0000-0000-0000-000000000005', 'HP Pavilion Plus 14', 'HP', 849, 'Intel Core Ultra 7 258V', 'Intel Arc 140V integrated', 16, 512, 14, 'OLED 2.8K 120Hz', 1.46, 12, 'Windows 11', ARRAY['content', 'student', 'office', 'media']::text[], 70, 80, 80, 72, 1, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=hp%20pavilion%20plus%2014%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://hp.com/pavilion-plus-14', 'Excellent 2.8K OLED display at this price point. Great for media consumption and content creation basics.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
  ('00000000-0000-0000-0000-000000000006', 'MacBook Air 13 M5', 'Apple', 1299, 'Apple M5 (10-core)', 'Integrated M5 10-core', 16, 512, 13.6, 'Liquid Retina IPS 60Hz', 1.26, 19, 'macOS', ARRAY['business', 'office', 'content', 'developer', 'student', 'travel']::text[], 80, 94, 82, 86, 1, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=macbook%20air%2013%20m5%20midnight%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://apple.com/macbook-air-13', 'The benchmark midrange laptop. Silent, incredible battery, strong single-core performance. 16GB is the sweet spot for software dev.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
  ('00000000-0000-0000-0000-000000000007', 'MacBook Air 15 M5', 'Apple', 1499, 'Apple M5 (10-core)', 'Integrated M5 10-core', 16, 512, 15.3, 'Liquid Retina IPS 60Hz', 1.51, 20, 'macOS', ARRAY['business', 'office', 'content', 'developer', 'media', 'travel']::text[], 80, 88, 78, 86, 1, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=macbook%20air%2015%20m5%20starlight%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://apple.com/macbook-air-15', 'Same M5 chip as the 13-inch, but bigger screen and speakers for media. Still remarkably light.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
  ('00000000-0000-0000-0000-000000000008', 'ASUS Zenbook A14', 'ASUS', 1399, 'AMD Ryzen AI 9 370', 'AMD Radeon 890M integrated', 32, 1024, 14, 'OLED 3K 120Hz', 1.22, 16, 'Windows 11', ARRAY['developer', 'business', 'content', 'creator', 'travel']::text[], 86, 95, 84, 88, 1, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=asus%20zenbook%20a14%20blue%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://asus.com/zenbook-a14', 'Zenbook flagship ultrabook. 32GB LPDDR5X + 1TB + Ryzen AI 9. Top-tier display, NPUs for on-device AI workloads.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
  ('00000000-0000-0000-0000-000000000009', 'HP OmniBook Ultra 14', 'HP', 1599, 'Intel Core Ultra 9 288V', 'Intel Arc 150V integrated', 32, 1024, 14, 'OLED 2.8K 120Hz', 1.3, 15, 'Windows 11', ARRAY['business', 'developer', 'creator', 'content', 'travel']::text[], 85, 92, 80, 88, 1, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=hp%20omnibook%20ultra%2014%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://hp.com/omnibook-ultra-14', 'HP''s premium ultrabook. Strong Intel Ultra 9, 32GB unified RAM, premium build. Great for developers and mobile professionals.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
  ('00000000-0000-0000-0000-000000000010', 'Framework 13 2026', 'Framework', 1349, 'AMD Ryzen AI 7 360', 'AMD Radeon 880M integrated', 32, 1024, 13, 'IPS QHD 120Hz', 1.29, 13, 'Windows 11', ARRAY['developer', 'tinkerer', 'student', 'business']::text[], 82, 90, 86, 96, 1, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=framework%2013%202026%20repairable%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://frame.work/13', 'Fully repairable and upgradable. User-replaceable CPU, RAM, SSD, ports, and battery. Highest future-proof score in the lineup.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
  ('00000000-0000-0000-0000-000000000011', 'ThinkPad X1 Carbon Gen 13', 'Lenovo', 1899, 'Intel Core Ultra 7 268V', 'Intel Arc 140V integrated', 32, 1024, 14, 'IPS 2.2K 120Hz Touch', 1.12, 16, 'Windows 11', ARRAY['business', 'developer', 'travel', 'office']::text[], 78, 96, 70, 82, 1, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=thinkpad%20x1%20carbon%20gen%2013%20black%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://lenovo.com/x1-carbon', 'The classic business machine. Best keyboard on the market, legendary build quality, MIL-STD durability. Price premium for the brand.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
  ('00000000-0000-0000-0000-000000000012', 'Dell XPS 14 2026', 'Dell', 1999, 'Intel Core Ultra 9 288V', 'NVIDIA GeForce RTX 4060 8GB', 32, 1024, 14.5, 'OLED 3.2K 120Hz Touch', 1.45, 12, 'Windows 11', ARRAY['creator', 'developer', 'gaming_light', 'content', 'media']::text[], 90, 82, 74, 90, 3, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=dell%20xps%2014%202026%20titanium%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://dell.com/xps-14', 'Premium ultrabook with discrete RTX 4060 GPU. Balances performance with portability. Great for video editing and light gaming.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
  ('00000000-0000-0000-0000-000000000013', 'MacBook Pro 14 M5 Pro', 'Apple', 2299, 'Apple M5 Pro (12-core)', 'Integrated M5 Pro 16-core', 32, 1024, 14.2, 'Mini-LED ProMotion 120Hz HDR', 1.55, 18, 'macOS', ARRAY['creator', 'developer', 'content', 'media', 'ml_light']::text[], 95, 86, 80, 94, 1, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=macbook%20pro%2014%20m5%20pro%20space%20black%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://apple.com/macbook-pro-14', 'Creator-level performance in a 14-inch form. Incredible unified memory bandwidth, class-leading display, HDMI + SDXC ports.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
  ('00000000-0000-0000-0000-000000000014', 'MacBook Pro 16 M5 Max', 'Apple', 3499, 'Apple M5 Max (16-core)', 'Integrated M5 Max 40-core', 64, 2048, 16.2, 'Mini-LED ProMotion 120Hz HDR', 2.14, 20, 'macOS', ARRAY['creator', 'ml', 'developer', 'video_editing', '3d']::text[], 100, 66, 72, 98, 1, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=macbook%20pro%2016%20m5%20max%20space%20black%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://apple.com/macbook-pro-16', 'Top-tier creator machine. 64GB unified memory, massive GPU. Ideal for 8K video editing, 3D, and local ML fine-tuning. Heavy.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
  ('00000000-0000-0000-0000-000000000015', 'Lenovo Yoga Pro 9i Gen 9', 'Lenovo', 2199, 'Intel Core Ultra 9 288H', 'NVIDIA GeForce RTX 4070 8GB', 32, 1024, 16, 'Mini-LED 3.2K 165Hz HDR', 2.08, 10, 'Windows 11', ARRAY['creator', 'gaming', 'developer', 'video_editing', '3d']::text[], 96, 64, 82, 92, 4, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=lenovo%20yoga%20pro%209i%20gen%209%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://lenovo.com/yoga-pro-9i', 'Creator-focused workstation. Amazing Mini-LED screen, RTX 4070, strong cooling. A touch heavy but incredibly capable.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
  ('00000000-0000-0000-0000-000000000016', 'Lenovo LOQ 15 2026', 'Lenovo', 1099, 'AMD Ryzen 7 9800HS', 'NVIDIA GeForce RTX 4060 8GB', 16, 512, 15.6, 'IPS FHD 144Hz', 2.38, 7, 'Windows 11', ARRAY['gaming', 'student', 'content']::text[], 88, 54, 88, 80, 3, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=lenovo%20loq%2015%202026%20gaming%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://lenovo.com/loq-15', 'Best budget gaming laptop. RTX 4060 handles 1080p high / 1440p medium with ease. Plastic build, heavy, short battery.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
  ('00000000-0000-0000-0000-000000000017', 'Acer Nitro V 16', 'Acer', 999, 'AMD Ryzen 7 8845HS', 'NVIDIA GeForce RTX 4060 8GB', 16, 512, 16, 'IPS WQXGA 165Hz', 2.3, 6, 'Windows 11', ARRAY['gaming', 'student']::text[], 84, 52, 86, 76, 3, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=acer%20nitro%20v%2016%20gaming%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://acer.com/nitro-v-16', 'Aggressively priced RTX 4060 machine. 165Hz WQXGA display is a bonus. Thermal throttling under sustained load.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
