  ('00000000-0000-0000-0000-000000000019', 'ASUS ROG Zephyrus G14', 'ASUS', 1899, 'AMD Ryzen 9 9900HS', 'NVIDIA GeForce RTX 4070 8GB', 32, 1024, 14, 'OLED QHD+ 120Hz', 1.72, 9, 'Windows 11', ARRAY['gaming', 'creator', 'travel', 'content']::text[], 93, 76, 78, 90, 4, 'https://coresg-normal.trae.ai/api/ide/v1/text_to_image?prompt=asus%20rog%20zephyrus%20g14%20white%20laptop%20on%20white%20background%20product%20photo&image_size=square_hd', 'https://asus.com/rog-zephyrus-g14', 'The compact gaming ultrabook. RTX 4070 in a 14-inch, 1.72kg package. Perfect blend of power and portability.', '2026-01-15T00:00:00Z', '2026-01-15T00:00:00Z'),
